  assert.equal(isContentCallReply(msg('<think>plan</think>{"command": "ls"}'), only("run_command")), true);
  assert.equal(isContentCallReply(msg('{"name": "run_command", "arguments": {"command": "ls"}}'), HARNESS_TOOLS), true);
