/**
 * CS-11: OpenHands' stuck-detector patterns replayed as scripted transcripts against the real agent turn.
 * Each ends BLOCKED, recovered (a Nexus note reached the model and the turn then finished), or is recorded with the
 * reason the existing guard already stops it.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import "./helpers/leak_guard.js";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION, HarnessConfig } from "../src/types.js";
import { startGateway, makeRepo, Reply } from "./helpers/fixtures.js";

const cfg = (endpoint: string, workspace: string, continuation = true): HarnessConfig => ({
  endpoint, model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true,
  ...(continuation ? { continuation: { ...DEFAULT_CONTINUATION } } : {}),
});
const tool = (name: string, args: unknown): Reply => ({ kind: "tools", calls: [{ name, args }] });
const text = (content: string): Reply => ({ kind: "text", content });
const notes = (agent: AutonomousAgent, needle: string): number =>
  (agent as any).messages.filter((m: any) => typeof m.content === "string" && m.content.includes(needle)).length;

async function withAgent(continuation: boolean, files: Record<string, string>, replies: Reply[], body: (agent: AutonomousAgent, gw: Awaited<ReturnType<typeof startGateway>>) => Promise<void>) {
  const repo = makeRepo(files);
  const gw = await startGateway((n) => replies[n - 1] ?? text("finished"));
  const agent = new AutonomousAgent(cfg(gw.url, repo, continuation));
  (agent as any).ui = new Proxy({}, { get: () => () => {} });
  try { await body(agent, gw); } finally { agent.shutdown(); await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
}

const probe = (label: string, turn: any, agent: AutonomousAgent, gw: any) =>
  console.log("PROBE", label, JSON.stringify({ execution: turn.execution, outcome: turn.outcome, reason: turn.reason, requests: gw.requests.length, recovery: notes(agent, "Nexus recovery"), same: notes(agent, "with the same arguments") }));

describe("CS-11 probes", () => {
  const read = tool("read_file", { path: "a.txt" });
  const readB = tool("read_file", { path: "b.txt" });
  test("P1 same action and result x4", { timeout: 90_000 }, async () => {
    await withAgent(true, { "a.txt": "hello\n" }, [read, read, read, read, text("done")], async (agent, gw) => { probe("P1", await agent.runTurn("Read a.txt."), agent, gw); });
  });
  test("P2a same command failing identically x3", { timeout: 90_000 }, async () => {
    const f = tool("run_command", { command: "echo broken; exit 1" });
    await withAgent(true, { "a.txt": "x\n" }, [f, f, f, f, f, text("done")], async (agent, gw) => { probe("P2a", await agent.runTurn("Fix it."), agent, gw); });
  });
  test("P2b same command failing with changing text x6", { timeout: 90_000 }, async () => {
    const f = tool("run_command", { command: "echo \"broken $(date +%N)\"; exit 1" });
    await withAgent(true, { "a.txt": "x\n" }, [f, f, f, f, f, f, f, text("done")], async (agent, gw) => { probe("P2b", await agent.runTurn("Fix it."), agent, gw); });
  });
  test("P3 three text-only replies", { timeout: 90_000 }, async () => {
    await withAgent(true, { "a.txt": "x\n" }, [text("I will look into it."), text("Still looking into it."), text("Looking into it more."), text("Thinking."), text("Hmm.")], async (agent, gw) => { probe("P3", await agent.runTurn("Fix the bug in a.txt."), agent, gw); });
  });
  test("P4a A/B observer ping-pong x6", { timeout: 90_000 }, async () => {
    await withAgent(true, { "a.txt": "a\n", "b.txt": "b\n" }, [read, readB, read, readB, read, readB, read, readB, read, readB, read, readB, text("done")], async (agent, gw) => { probe("P4a", await agent.runTurn("Compare."), agent, gw); });
  });
  test("P4b A/B command ping-pong x6", { timeout: 120_000 }, async () => {
    const a = tool("run_command", { command: "echo A; exit 1" });
    const b = tool("run_command", { command: "echo B; exit 1" });
    await withAgent(true, { "a.txt": "a\n" }, [a, b, a, b, a, b, a, b, a, b, a, b, text("done")], async (agent, gw) => { probe("P4b", await agent.runTurn("Fix."), agent, gw); });
  });
});
EOF
