/**
 * VC-7: the DV-2 non-convergence stop fires on the run_tests path too, and for an operator-configured verifier run
 * through run_tests, not only when the model calls task_completed. The turn ends BLOCKED with the attempt history.
 */
import { test, describe } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import "./helpers/leak_guard.js";
import { AutonomousAgent } from "../src/agent.js";
import { DEFAULT_CONTINUATION, HarnessConfig } from "../src/types.js";
import { startGateway, makeRepo, Reply } from "./helpers/fixtures.js";

const cfg = (endpoint: string, workspace: string, extra: Partial<HarnessConfig> = {}): HarnessConfig => ({
  endpoint, model: "m", maxSteps: 30, temperature: 0, workspace, shell: "bash", approvalMode: "auto", fullAccess: true,
  continuation: { ...DEFAULT_CONTINUATION }, ...extra,
});
const write = (name: string): Reply => ({ kind: "tools", calls: [{ name: "write_file", args: { path: name, content: `${name}\n` } }] });
const runTests: Reply = { kind: "tools", calls: [{ name: "run_tests", args: {} }] };
const script = (...replies: Reply[]) => (n: number): Reply => replies[n - 1] ?? { kind: "text", content: "stopping" };
const STALLED = "test:\n\t@echo 'not ok 1 - adds numbers'\n\t@echo 'ℹ tests 1'\n\t@exit 1\n";
const CHANGING = "test:\n\t@echo \"not ok 1 - t$$(ls | wc -l)\"\n\t@echo 'ℹ tests 1'\n\t@exit 1\n";

async function withTurn(makefile: string, replies: Reply[], extra: Partial<HarnessConfig>, body: (agent: AutonomousAgent, gw: Awaited<ReturnType<typeof startGateway>>) => Promise<void>) {
  const repo = makeRepo({ Makefile: makefile });
  const gw = await startGateway(script(...replies));
  const agent = new AutonomousAgent(cfg(gw.url, repo, extra));
  (agent as any).ui = new Proxy({}, { get: () => () => {} });
  try { await body(agent, gw); } finally { agent.shutdown(); await gw.close(); fs.rmSync(repo, { recursive: true, force: true }); }
}

describe("VC-7 convergence on the run_tests path", () => {
  test("a run_tests-only loop: three candidates failing the same check end BLOCKED with the history attached", { timeout: 90_000 }, async () => {
    await withTurn(STALLED, [write("a.txt"), runTests, write("b.txt"), runTests, write("c.txt"), runTests, write("d.txt"), runTests], {}, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.equal(turn.execution, "BLOCKED");
      assert.equal(turn.outcome, "NOT_ESTABLISHED");
      assert.equal(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.convergence?.state, "stalled");
      assert.equal(turn.convergence?.attempts.length, 3);
      assert.equal(new Set(turn.convergence?.attempts.map((a) => a.candidate)).size, 3);
      assert.equal(gw.requests.length, 6, "no inference request after the third failing run_tests");
    });
  });

  test("an operator-configured verifier run through run_tests stops the same way", { timeout: 90_000 }, async () => {
    await withTurn(STALLED, [write("a.txt"), runTests, write("b.txt"), runTests, write("c.txt"), runTests, write("d.txt"), runTests], { authoritativeVerifierCommand: "make test" }, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.equal(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.convergence?.attempts.every((a) => a.command === "make test"), true);
      assert.equal(gw.requests.length, 6);
    });
  });

  test("a changing failure set on the run_tests path does not stop the turn", { timeout: 90_000 }, async () => {
    await withTurn(CHANGING, [write("a.txt"), runTests, write("b.txt"), runTests, write("c.txt"), runTests, { kind: "text", content: "I will leave it here." }], {}, async (agent, gw) => {
      const turn = await agent.runTurn("Make the build pass.");
      assert.notEqual(turn.reason, "VERIFIER_NOT_CONVERGING");
      assert.equal(turn.convergence, undefined);
      assert.ok(gw.requests.length >= 7);
    });
  });
});
EOF
node scripts/run_tests.mjs test/vc7_convergence.test.ts 2>&1 | grep -E "^ℹ (tests|pass|fail)|✖|actual|expected|Error" | head -20

